import re
from datetime import datetime, timedelta

# Login
pw = apis.supervisor.show_account_passwords(); creds={p['account_name']:p['password'] for p in pw}
gmail_token = apis.gmail.login(username='morgan-harrison@gmail.com', password=creds['gmail'])['access_token']
fs_token = apis.file_system.login(username='morgan-harrison@gmail.com', password=creds['file_system'])['access_token']

now = datetime.now()
weekday = now.weekday() # Mon=0
sat_delta = (5 - weekday) % 7
sun_delta = (6 - weekday) % 7
sat_date = (now + timedelta(days=sat_delta)).date()
sun_date = (now + timedelta(days=sun_delta)).date()
print('now:', now)
print('this weekend (assumed Sat-Sun):', sat_date.isoformat(), 'to', sun_date.isoformat())

# Fetch all threads in inbox+archived containing Santorini with attachments

def fetch_all_threads(api_func, query, attachment=True):
    results=[]
    page_index=0
    while True:
        page = api_func(access_token=gmail_token, query=query, attachment=attachment, page_index=page_index, page_limit=20)
        items = page.get('success', []) if isinstance(page, dict) else page
        if not items:
            break
        results.extend(items)
        page_index += 1
        if page_index>200:
            break
    return results

inbox = fetch_all_threads(apis.gmail.show_inbox_threads, query='Santorini', attachment=True)
arch = fetch_all_threads(apis.gmail.show_archived_threads, query='Santorini', attachment=True)
print('threads inbox Santorini+attachments:', len(inbox))
print('threads archived Santorini+attachments:', len(arch))

thread_by_id={}
for t in inbox+arch:
    thread_by_id[t['email_thread_id']] = t
thread_summaries = list(thread_by_id.values())
print('unique thread summaries:', len(thread_summaries))

# Parse each thread for flight date in weekend and ticket attachments

def parse_confirmed_dates(text):
    # look for ISO date after 'confirmed for'
    dates=[]
    for m in re.finditer(r'confirmed for\s*(\d{4}-\d{2}-\d{2})', text, flags=re.IGNORECASE):
        try:
            dates.append(datetime.fromisoformat(m.group(1)).date())
        except Exception:
            pass
    # also support 'confirmed for May 21' or 'confirmed for 21 May'
    for m in re.finditer(r'confirmed for\s*([A-Za-z]{3,9})\s*(\d{1,2})', text, flags=re.IGNORECASE):
        mon = m.group(1).lower()[:9]
        day = int(m.group(2))
        months = {'jan':1,'january':1,'feb':2,'february':2,'mar':3,'march':3,'apr':4,'april':4,'may':5,'jun':6,'june':6,'jul':7,'july':7,'aug':8,'august':8,'sep':9,'sept':9,'september':9,'oct':10,'october':10,'nov':11,'november':11,'dec':12,'december':12}
        if mon in months:
            try:
                dates.append(datetime(now.year, months[mon], day).date())
            except Exception:
                pass
    return sorted(set(dates))


def get_ticket_attachments(thread):
    emails = thread.get('emails', []) if isinstance(thread, dict) else []
    drafts = thread.get('drafts', []) if isinstance(thread, dict) else []
    all_attachments=[]
    for e in emails:
        all_attachments.extend(e.get('attachments', []))
    for d in drafts:
        all_attachments.extend(d.get('attachments', []))

    pdfs=[a for a in all_attachments if (a.get('file_name','') or '').lower().endswith('.pdf')]
    if not pdfs:
        return []

    # prefer those whose filename includes 'ticket'
    ticket_like=[a for a in pdfs if 'ticket' in (a.get('file_name','') or '').lower()]
    if ticket_like:
        return ticket_like
    # otherwise take all pdfs
    return pdfs

plan=[]

for ts in thread_summaries:
    tid = ts['email_thread_id']
    thr_page = apis.gmail.show_thread(email_thread_id=tid, access_token=gmail_token)
    thr = thr_page.get('success', thr_page) if isinstance(thr_page, dict) else None
    if not isinstance(thr, dict):
        continue

    # gather full text from emails + drafts
    full_parts=[]
    for e in thr.get('emails', []):
        full_parts.append(e.get('subject',''))
        full_parts.append(e.get('body',''))
    for d in thr.get('drafts', []):
        full_parts.append(d.get('subject',''))
        full_parts.append(d.get('body',''))
    full_text='\n'.join(full_parts)
    if 'santorini' not in full_text.lower():
        continue

    confirmed_dates = parse_confirmed_dates(full_text)
    weekend_dates = [d for d in confirmed_dates if sat_date <= d <= sun_date]
    if not weekend_dates:
        continue

    ticket_atts = get_ticket_attachments(thr)
    if not ticket_atts:
        continue

    for a in ticket_atts:
        plan.append({
            'email_thread_id': tid,
            'file_name': a.get('file_name'),
            'attachment_id': a.get('id'),
            'weekend_dates': [dd.isoformat() for dd in weekend_dates]
        })

# de-dupe by attachment_id
uniq={}
for p in plan:
    uniq[p['attachment_id']]=p
plan=list(uniq.values())

print('download plan size (ticket pdfs):', len(plan))
for p in sorted(plan, key=lambda x: x['email_thread_id'])[:20]:
    print(p)

# Ensure destination dir exists
# Create if not exists
print('dest dir check/creation')
if not apis.file_system.directory_exists(directory_path='~/documents/personal/', access_token=fs_token).get('exists', False):
    apis.file_system.create_directory(directory_path='~/documents/personal/', access_token=fs_token, recursive=True, allow_if_exists=True)

# Download the planned ticket attachment(s) to ~/documents/personal/

from datetime import datetime

# Ensure we have gmail_token, fs_token, plan
try:
